        #region Mutagen
        public IEnumerable<IFormLinkGetter> EnumerateFormLinks(ILeveledItemGetter obj, bool iterateNestedRecords = true)
        {
            foreach (var item in base.EnumerateFormLinks(obj, iterateNestedRecords))
            {
                yield return item;
            }
            if (FormLinkInformation.TryFactory(obj.PreviewTransform, out var PreviewTransformInfo))
            {
                yield return PreviewTransformInfo;
            }
            if (FormLinkInformation.TryFactory(obj.DefaultLayer, out var DefaultLayerInfo))
            {
                yield return DefaultLayerInfo;
            }
            if (FormLinkInformation.TryFactory(obj.MaxGlobal, out var MaxGlobalInfo))
            {
                yield return MaxGlobalInfo;
            }
            if (FormLinkInformation.TryFactory(obj.MaxCurveTable, out var MaxCurveTableInfo))
            {
                yield return MaxCurveTableInfo;
            }
            if (FormLinkInformation.TryFactory(obj.ChanceNoneGlobal, out var ChanceNoneGlobalInfo))
            {
                yield return ChanceNoneGlobalInfo;
            }
            if (FormLinkInformation.TryFactory(obj.ChanceNoneCurveTable, out var ChanceNoneCurveTableInfo))
            {
                yield return ChanceNoneCurveTableInfo;
            }
            if (FormLinkInformation.TryFactory(obj.SubGlobal, out var SubGlobalInfo))
            {
                yield return SubGlobalInfo;
            }
            if (FormLinkInformation.TryFactory(obj.Quest, out var QuestInfo))
            {
                yield return QuestInfo;
            }
            if (obj.Model is {} ModelItems)
            {
                foreach (var item in ModelItems.EnumerateFormLinks(iterateNestedRecords))
                {
                    yield return item;
                }
            }
            if (obj.Conditions is {} ConditionsItem)
            {
                foreach (var item in ConditionsItem.WhereCastable<IConditionGetter, IFormLinkContainerGetter>()
                    .SelectMany((f) => f.EnumerateFormLinks(iterateNestedRecords)))
                {
                    yield return FormLinkInformation.Factory(item);
                }
            }
            if (FormLinkInformation.TryFactory(obj.LVIT, out var LVITInfo))
            {
                yield return LVITInfo;
            }
            if (FormLinkInformation.TryFactory(obj.LVLT, out var LVLTInfo))
            {
                yield return LVLTInfo;
            }
            if (FormLinkInformation.TryFactory(obj.LVOG, out var LVOGInfo))
            {
                yield return LVOGInfo;
            }
            if (FormLinkInformation.TryFactory(obj.LVOT, out var LVOTInfo))
            {
                yield return LVOTInfo;
            }
            yield break;
        }
        
